import { test, expect } from '@playwright/test';
import * as ui from '../support/ui';

test.setTimeout(240_000);
test.describe("score", () => {
  test("score", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-03-01");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "20.00"})).toBe(true);
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
    const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B"}));
    await ui.setSetting(pg_uma, "terms", "5");
    const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "3000.00"}));
    const c_ada_1 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "250.00"}));
    const c_ben_0 = ui.must(await ui.addClaim(pg_uma, p_ben, {"amount": "100.00"}));
    expect(await ui.claimAction(pg_uma, c_ada_0, "open")).toBe(true);
    expect(await ui.claimAction(pg_uma, c_ada_1, "open")).toBe(true);
    expect(await ui.claimAction(pg_uma, c_ben_0, "open")).toBe(true);
    const pg_vic = await ui.userPage(browser, "vic", sheet);
    expect(await ui.claimAction(pg_vic, c_ada_0, "settle")).toBe(true);
    expect(await ui.claimAction(pg_vic, c_ada_1, "settle")).toBe(true);
    await ui.refresh(pg_uma);
    const c_ada_2 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "-1000.00", "corrects": "FY2026-1"}));
    expect(await ui.claimAction(pg_uma, c_ada_2, "open")).toBe(true);
    await ui.refresh(pg_vic);
    expect(await ui.claimAction(pg_vic, c_ada_2, "settle")).toBe(true);
    await ui.refresh(pg_vic);
    await expect(pg_vic.getByTestId("person-row-" + p_ada).getByTestId("person-score")).toHaveText("2");
    await expect(pg_vic.getByTestId("person-row-" + p_ada).getByTestId("person-due-total")).toHaveText("225.00");
    await expect(pg_vic.getByTestId("person-row-" + p_ben).getByTestId("person-score")).toHaveText("0");
    await expect(pg_vic.getByTestId("person-row-" + p_ben).getByTestId("person-due-total")).toHaveText("20.00");
    await ui.refresh(pg_uma);
    await ui.setToday(pg_uma, "2026-03-20");
    await ui.refresh(pg_uma);
    await expect(pg_uma.getByTestId("person-row-" + p_ada).getByTestId("person-score")).toHaveText("2");
    await expect(pg_uma.getByTestId("person-row-" + p_ada).getByTestId("person-overdue-count")).toHaveText("0");
    await expect(pg_uma.getByTestId("person-row-" + p_ben).getByTestId("person-score")).toHaveText("-5");
    await expect(pg_uma.getByTestId("person-row-" + p_ben).getByTestId("person-overdue-count")).toHaveText("1");
    await ui.expectAudit(sheet, [
      `RATE_SET sheet=${sheet} by=uma grade=A rate=10.00`,
      `RATE_SET sheet=${sheet} by=uma grade=B rate=20.00`,
      `PERSON_ADDED sheet=${sheet} by=uma name=Ada grade=A`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=0.00 due-total=0.00 overdue-total=0.00`,
      `PERSON_ADDED sheet=${sheet} by=uma name=Ben grade=B`,
      `ROLLUP sheet=${sheet} by=uma person=Ben claimed=0.00 due-total=0.00 overdue-total=0.00`,
      `SETTING_CHANGED sheet=${sheet} by=uma key=terms value=5`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Ada amount=3000.00 date=2026-03-01`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Ada amount=250.00 date=2026-03-01`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Ben amount=100.00 date=2026-03-01`,
      `CLAIM_OPENED sheet=${sheet} by=uma person=Ada amount=3000.00 date=2026-03-01`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=3000.00 due-total=300.00 overdue-total=0.00`,
      `TOTALS sheet=${sheet} by=uma claimed-total=3000.00 due-total=300.00 overdue-total=0.00`,
      `CLAIM_OPENED sheet=${sheet} by=uma person=Ada amount=250.00 date=2026-03-01`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=3250.00 due-total=325.00 overdue-total=0.00`,
      `TOTALS sheet=${sheet} by=uma claimed-total=3250.00 due-total=325.00 overdue-total=0.00`,
      `CLAIM_OPENED sheet=${sheet} by=uma person=Ben amount=100.00 date=2026-03-01`,
      `ROLLUP sheet=${sheet} by=uma person=Ben claimed=100.00 due-total=20.00 overdue-total=0.00`,
      `TOTALS sheet=${sheet} by=uma claimed-total=3350.00 due-total=345.00 overdue-total=0.00`,
      `CLAIM_SETTLED sheet=${sheet} by=vic person=Ada amount=3000.00 date=2026-03-01 number=FY2026-1 due=300.00`,
      `CLAIM_SETTLED sheet=${sheet} by=vic person=Ada amount=250.00 date=2026-03-01 number=FY2026-2 due=25.00`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Ada amount=-1000.00 date=2026-03-01`,
      `CLAIM_OPENED sheet=${sheet} by=uma person=Ada amount=-1000.00 date=2026-03-01`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=3250.00 due-total=225.00 overdue-total=0.00`,
      `TOTALS sheet=${sheet} by=uma claimed-total=3350.00 due-total=245.00 overdue-total=0.00`,
      `CLAIM_SETTLED sheet=${sheet} by=vic person=Ada amount=-1000.00 date=2026-03-01 number=FY2026-3 due=-100.00`,
      `SNAPSHOT sheet=${sheet} by=uma name=Ada due-total=225.00`,
      `SNAPSHOT sheet=${sheet} by=uma name=Ben due-total=20.00`,
      `ROLLUP sheet=${sheet} by=uma person=Ben claimed=100.00 due-total=20.00 overdue-total=20.00`,
      `TOTALS sheet=${sheet} by=uma claimed-total=3350.00 due-total=245.00 overdue-total=20.00`
    ]);
  });
